import re

from ute_testline_configuration.ute_config import Host, Pdu, FSMr3, RF, FSMr4

from .loader import TestlineParametersLoader
from .utils import config_vars_to_dict


class Testline(TestlineParametersLoader):

    def __init__(self, location, testline_name, env_config_id, provider=None):
        super(Testline, self).__init__(location, testline_name, env_config_id, provider)

    def __str__(self):
        return "Testline: {tl_name}. Location {loc}. Env config path: {path}".format(tl_name=self.testline,
                                                                                     loc=self.location,
                                                                                     path=self.env_config_path)

    @property
    def testline_config_variables(self):
        return self.testline_parameters.TESTLINE_CONFIG_VARIABLES

    def env_config_testline_variables(self):
        return config_vars_to_dict(self.env_config.TESTLINE_CONFIG_VARIABLES)

    def bts_id(self):
        bts_id = re.search(r'_(\d+)_', self.env_config.TESTLINE_NAME)
        return bts_id.group(1)

    @staticmethod
    def host(addr):
        return Host(addr=addr)

    def msm_host_addr(self):
        host_msm = self.env_config.PC_IP1
        return host_msm

    def esm_host_addr(self):
        try:
            host_esm = self.env_config.PC_IP2
        except AttributeError:
            host_esm = None
        return host_esm

    def _get_mplane_ip(self):
        try:
            mplane_ip = self.env_config.MPLANE_IP
        except AttributeError:
            mplane_ip = None
        return mplane_ip

    def rf(self, module):
        """
        :param module: dictionary with module data containing information about pdu ip, outlet and type
        :return: RF object
        """
        return RF(pdu=self.pdu(module))

    def fsm3(self, module):
        """
        :param module: dictionary with module data containing information about pdu ip, outlet and type
        :return: FSMr3 object
        """
        return FSMr3(pdu=self.pdu(module))

    def fsm4(self, module):
        """
        Supports only ASIA (FSIP) SM
        :param module: dictionary with module data containing information about pdu ip, outlet and type
        :return: FSMr4 object
        """
        return FSMr4(hw_type='FSIP', pdu=self.pdu(module))

    @staticmethod
    def pdu(module):
        """
        :param module: dictionary with pdu data containing information about ip, outlet and its type
        :return: Pdu object
        """
        return Pdu(module['IP'], module['OUTLET'], module['TYPE'])
